// ---- hand-written (G module) ----

const publish = (id: number, published = true, who: keyof typeof tokens = 'admin') =>
  call(who, 'put', `/${id}/published`, { published })
/** A bulletin added and published through the API. */
const published = async (over: object = {}) => {
  const row = await add(body(unique(), over))
  await publish(row.id).expect(200)
  return row as { id: number; title: string }
}
const feed = (who: keyof typeof tokens, path = '', method: 'get' | 'post' = 'get') =>
  call(who, method, `/feed${path}`)
const publishedCount = async () =>
  Number(
    (
      await ds.query(
        'SELECT COUNT(*) AS n FROM msg_bulletin WHERE published = 1 AND deleted_at IS NULL',
      )
    )[0].n,
  )

describe('crud (hand-written): sanitized body, kinds, publishing', () => {
  it('crud: the body keeps the allow-list only: style, on* and javascript: stripped on create and update', async () => {
    const dirty =
      '<p style="color:red" onclick="alert(1)">Hi <a href="javascript:alert(1)" target="_blank">x</a></p>' +
      '<img src=x onerror=alert(1)><script>alert(2)</script><iframe src="https://evil.example"></iframe>' +
      '<img src="/files/2026/09/27/a.png" alt="a" style="width:10px"><img src="data:image/png;base64,AAAA">'
    const clean =
      '<p>Hi <a target="_blank" rel="noopener noreferrer">x</a></p><img src="x" />' +
      '<img src="/files/2026/09/27/a.png" alt="a" /><img />'
    const row = await add(body(unique(), { body: dirty }))
    expect(row.body).toBe(clean)
    const [stored] = await ds.query('SELECT body FROM msg_bulletin WHERE id = ?', [row.id])
    expect(stored.body).toBe(clean)
    await call('admin', 'put', `/${row.id}`, {
      body: '<p onmouseover="x()">B</p><a href="JaVaScRiPt:alert(1)">y</a><svg onload="alert(1)"></svg>',
    }).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data.body).toBe(
      '<p>B</p><a rel="noopener noreferrer">y</a>',
    )
  })

  it('crud: kind is a bulletin kind code', async () => {
    await add(body(unique(), { kind: 'announcement' }))
    const res = await create(body(unique(), { kind: 'memo' })).expect(400)
    expect(res.body.errors).toEqual([{ path: 'kind', msg: expect.any(String) }])
  })

  it('crud: a new bulletin is a draft; publish sets publishedAt, taking it back clears it; perm publish', async () => {
    const row = await add(body(unique()))
    expect(row).toMatchObject({ published: false, publishedAt: null })
    const trace = `${PREFIX}${process.pid}-pub`
    await publish(row.id).set('X-Request-Id', trace).expect(200)
    const on = (await call('admin', 'get', `/${row.id}`)).body.data
    expect(on.published).toBe(true)
    expect(Date.now() - new Date(on.publishedAt).getTime()).toBeLessThan(60_000)
    // the same state again changes nothing
    await publish(row.id).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data.publishedAt).toBe(on.publishedAt)
    expect(await logOf(ds, trace)).toMatchObject({ verb: 'publish', biz_id: String(row.id), ok: 1 })
    // the list filters by it
    const drafts = await call('admin', 'get').query({ published: 'false', pageSize: 200 })
    expect(idsOf(drafts)).not.toContain(row.id)
    await publish(row.id, false).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data).toMatchObject({
      published: false,
      publishedAt: null,
    })
    expect((await publish(row.id, true, 'reader')).status).toBe(403)
    expect((await publish(MISSING)).status).toBe(404)
    await call('admin', 'put', `/${row.id}/published`, {}).expect(400)
  })
})

describe('read (hand-written): the readers’ feed and the receipts', () => {
  it('read: a user without any permission gets the latest 5 published (newest first) and the unread count', async () => {
    const draft = await add(body(unique()))
    const rows = []
    for (let i = 0; i < 6; i++) rows.push(await published())
    const res = await feed('plain').expect(200)
    expect(res.body.data.items).toEqual(
      rows
        .slice(1)
        .reverse()
        .map((r) => ({
          id: r.id,
          title: r.title,
          kind: 'notice',
          publishedAt: expect.any(String),
          read: false,
        })),
    )
    expect(res.body.data.items.map((r: { id: number }) => r.id)).not.toContain(draft.id)
    expect(res.body.data.unread).toBe(await publishedCount())
  })

  it('read: GET /feed/:id → the published one with its sanitized body, no receipt; a draft, deleted or unknown id → 404', async () => {
    const row = await published({ body: '<p onclick="x()">Read me</p>' })
    const res = await feed('plain', `/${row.id}`).expect(200)
    expect(res.body.data).toEqual({
      id: row.id,
      title: row.title,
      kind: 'notice',
      publishedAt: expect.any(String),
      read: false,
      body: '<p>Read me</p>',
    })
    // reading the detail leaves no receipt: the dialog posts `read` itself
    expect(
      await ds.query('SELECT 1 FROM msg_bulletin_receipt WHERE bulletin_id = ?', [row.id]),
    ).toEqual([])
    const draft = await add(body(unique()))
    const gone = await published()
    await call('admin', 'delete', `/${gone.id}`).expect(200)
    for (const id of [draft.id, gone.id, MISSING]) {
      for (const res of [await feed('plain', `/${id}`), await feed('plain', `/${id}/read`, 'post')])
        expect(res.status).toBe(404)
    }
    await feed('plain', '/abc').expect(400)
    await request(app.getHttpServer()).get(`${URL}/feed`).expect(401)
  })

  it('read: POST /feed/:id/read counts once and keeps the first read time; read-all reads every published one', async () => {
    const [a, b] = [await published(), await published()]
    const before = (await feed('plain').expect(200)).body.data.unread
    const first = await feed('plain', `/${a.id}/read`, 'post').expect(200)
    expect(first.body.data).toEqual({ unread: before - 1 })
    const [{ at }] = await ds.query(
      'SELECT read_at AS at FROM msg_bulletin_receipt WHERE bulletin_id = ? AND user_id = ?',
      [a.id, userIds[1]],
    )
    await new Promise((r) => setTimeout(r, 20))
    expect((await feed('plain', `/${a.id}/read`, 'post').expect(200)).body.data).toEqual({
      unread: before - 1,
    })
    const [again] = await ds.query(
      'SELECT read_at AS at FROM msg_bulletin_receipt WHERE bulletin_id = ? AND user_id = ?',
      [a.id, userIds[1]],
    )
    expect(again.at).toEqual(at)
    const items = (await feed('plain').expect(200)).body.data.items
    expect(items.find((r: { id: number }) => r.id === a.id).read).toBe(true)
    expect(items.find((r: { id: number }) => r.id === b.id).read).toBe(false)
    expect((await feed('plain', `/${a.id}`)).body.data.read).toBe(true)
    // another reader's count is its own
    expect((await feed('reader').expect(200)).body.data.unread).toBe(await publishedCount())
    expect((await feed('plain', '/read-all', 'post').expect(200)).body.data).toEqual({ unread: 0 })
    expect((await feed('plain').expect(200)).body.data.unread).toBe(0)
    // taken back and published again: still read (the receipt stays)
    await publish(b.id, false).expect(200)
    await publish(b.id).expect(200)
    expect((await feed('plain').expect(200)).body.data.unread).toBe(0)
    // nothing of it is action-logged: reading changes only the caller's own receipts (the interceptor
    // hands a row over before the response goes out, so a writer spy needs no wait)
    const action = vi.spyOn(app.get(AuditWriter), 'action')
    try {
      await feed('plain', `/${b.id}/read`, 'post').expect(200)
      await feed('plain', '/read-all', 'post').expect(200)
      expect(action).not.toHaveBeenCalled()
    } finally {
      action.mockRestore()
    }
  })

  it('read: a soft-deleted receipt counts as unread and is revived by read / read-all, read now (one row per link)', async () => {
    const [a, b] = [await published(), await published()]
    await feed('plain', '/read-all', 'post').expect(200)
    const receipt = (id: number) =>
      ds.query(
        'SELECT read_at AS at, deleted_at AS gone FROM msg_bulletin_receipt WHERE bulletin_id = ? AND user_id = ?',
        [id, userIds[1]],
      )
    const old = new Date(Date.UTC(2020, 0, 1))
    await ds.query(
      'UPDATE msg_bulletin_receipt SET deleted_at = NOW(3), read_at = ? WHERE bulletin_id IN (?) AND user_id = ?',
      [old, [a.id, b.id], userIds[1]],
    )
    expect((await feed('plain').expect(200)).body.data.unread).toBe(2)
    expect((await feed('plain', `/${a.id}`)).body.data.read).toBe(false)
    expect((await feed('plain', `/${a.id}/read`, 'post').expect(200)).body.data).toEqual({
      unread: 1,
    })
    expect((await feed('plain', '/read-all', 'post').expect(200)).body.data).toEqual({ unread: 0 })
    for (const id of [a.id, b.id]) {
      const rows = await receipt(id)
      expect(rows).toHaveLength(1)
      expect(rows[0].gone).toBeNull()
      expect(rows[0].at.getTime()).toBeGreaterThan(old.getTime())
    }
  })

  it('read: admin receipts: readers within the caller’s user data scope, keyword and sort; 403 without view; 404 unknown', async () => {
    const row = await published()
    await feed('plain', `/${row.id}/read`, 'post').expect(200)
    await new Promise((r) => setTimeout(r, 20))
    await feed('viewer', `/${row.id}/read`, 'post').expect(200)
    const receipts = (who: keyof typeof tokens, query: object = {}) =>
      call(who, 'get', `/${row.id}/receipts`).query(query)
    const all = (await receipts('admin').expect(200)).body.data
    expect(all.total).toBe(2)
    // newest read first by default
    expect(all.items).toEqual([
      {
        userId: userIds[2],
        username: `${PREFIX}viewer`,
        displayName: 'viewer',
        deptName: null,
        readAt: expect.any(String),
      },
      expect.objectContaining({ userId: userIds[1], username: `${PREFIX}plain` }),
    ])
    const names = (res: request.Response) =>
      res.body.data.items.map((r: { username: string }) => r.username)
    expect(names(await receipts('admin', { sort: 'username' }).expect(200))).toEqual([
      `${PREFIX}plain`,
      `${PREFIX}viewer`,
    ])
    expect(names(await receipts('admin', { keyword: 'plain' }).expect(200))).toEqual([
      `${PREFIX}plain`,
    ])
    // own_rows: the viewer sees only its own receipt
    expect(names(await receipts('viewer').expect(200))).toEqual([`${PREFIX}viewer`])
    expect((await receipts('reader')).status).toBe(403)
    expect((await receipts('plain')).status).toBe(403)
    await receipts('admin', { sort: 'displayName' }).expect(400)
    expect((await call('admin', 'get', `/${MISSING}/receipts`)).status).toBe(404)
    // a draft has none (not a 404)
    const draft = await add(body(unique()))
    expect((await call('admin', 'get', `/${draft.id}/receipts`).expect(200)).body.data).toEqual({
      items: [],
      total: 0,
    })
    // deleting the bulletin (soft) deletes its receipts (soft, the registry's cascade)
    const kept = await ds.query('SELECT 1 FROM msg_bulletin_receipt WHERE bulletin_id = ?', [
      row.id,
    ])
    expect(kept.length).toBeGreaterThan(0)
    await call('admin', 'delete', `/${row.id}`).expect(200)
    expect(
      await ds.query(
        'SELECT 1 FROM msg_bulletin_receipt WHERE bulletin_id = ? AND deleted_at IS NULL',
        [row.id],
      ),
    ).toEqual([])
    expect(
      await ds.query('SELECT 1 FROM msg_bulletin_receipt WHERE bulletin_id = ?', [row.id]),
    ).toEqual(kept)
  })
})

describe('push (hand-written): bulletin changes reach every signed-in socket', () => {
  it('push: publish, withdraw and deleting published ones → notify:bulletin with ids only; drafts and repeats stay quiet', async () => {
    // a user without any permission: every signed-in socket hears it
    const got = inbox(await connect(socketOf(app, { token: tokens.plain })))
    const heard = (n: number) => vi.waitFor(() => expect(got).toHaveLength(n), { timeout: 5000 })
    const msg = (action: string, ids: number[]) => ({
      type: RT.notifyBulletin,
      payload: { action, ids },
    })
    const a = await add(body(unique()))
    await publish(a.id).expect(200)
    await heard(1)
    // pushes arrive in order on the one socket: a quiet step is followed by a loud one, then counted
    await publish(a.id).expect(200)
    await publish(a.id, false).expect(200)
    await heard(2)
    const draft = await add(body(unique()))
    await call('admin', 'delete', `/${draft.id}`).expect(200)
    const b = await published()
    const c = await published()
    await publish(a.id).expect(200)
    await heard(5)
    const draft2 = await add(body(unique()))
    await call('admin', 'post', '/batch-delete', { ids: [draft2.id, b.id, a.id] }).expect(200)
    await call('admin', 'delete', `/${c.id}`).expect(200)
    await heard(7)
    expect(got).toEqual([
      msg('published', [a.id]),
      msg('withdrawn', [a.id]),
      msg('published', [b.id]),
      msg('published', [c.id]),
      msg('published', [a.id]),
      msg('deleted', [a.id, b.id]),
      msg('deleted', [c.id]),
    ])
    expect(JSON.stringify(got)).not.toContain('offline')
  })
})
